def load_drafts():
    raw=open(DRAFT,encoding='utf-8').read()
    dec=_json.JSONDecoder()
    k=raw.index('concat(')+len('concat(')
    arr,_=dec.raw_decode(raw[k:])
    return {l['id']:l for l in arr}

def build():
    drafts=load_drafts()
    obj={}
    for v in VIS:
        L=drafts[v['id']]
        frames=[]
        for f in v['frames']:
            fr={'t':f['t'],'say':f['say'],'v':f['v']}
            if f.get('prop'): fr['prop']=f['prop']
            frames.append(fr)
        lesson={
          'id': v['id'], 'title': L['title'], 'ico': L['ico'], 'src': L['src'],
          'subj': L['subj'], 'mode':'steps', 'scene': v['scene'], 'comic': frames,
          'check': L['check'], 'tasks': L['tasks'],
        }
        obj[v['id']]=lesson
    lines=['window.VIS7={};']
    for lid in sorted(obj):
        lines.append('window.VIS7['+str(lid)+']='+_json.dumps(obj[lid],ensure_ascii=False)+';')
    lines.append('(function(){for(var k in window.VIS7){var id=+k;for(var i=0;i<window.ARH_LESSONS.length;i++){if(window.ARH_LESSONS[i].id===id){window.ARH_LESSONS[i]=window.VIS7[id];break;}}}})();')
    open(OUT,'w',encoding='utf-8').write('\n'.join(lines))
    print('визуальных уроков волны C:',len(obj),'->',OUT,'ids:',sorted(obj))

if __name__=='__main__':
    build()
